import math


def calculate(left: float, operator: str, right: float) -> float:
    """Calculate one operation, rejecting invalid operators and zero divisors."""
    if operator == "+":
        return left + right
    if operator == "-":
        return left - right
    if operator == "*":
        return left * right
    if operator == "/":
        if right == 0:
            raise ValueError("Cannot divide by zero.")
        return left / right
    raise ValueError("Choose +, -, *, or /.")


def read_number(prompt: str, ans_available: bool = False, ans_value: float = None) -> float:
    """Read a finite number, allowing the user to retry invalid input. Accepts 'ans' if available."""
    while True:
        try:
            user_input = input(prompt)
            if user_input.strip().lower() == 'ans':
                if ans_available:
                    return ans_value
                else:
                    print("No previous answer available yet.")
                    continue
            number = float(user_input)
            if math.isfinite(number):
                return number
        except ValueError:
            pass
        print("Please enter a finite number.")


def main() -> None:
    print("Calculator: +, -, *, / (enter q to quit)")
    ans_available = False
    ans_value = None
    try:
        while True:
            operator = input("Operation: ").strip().lower()
            if operator in {"q", "quit", "exit"}:
                break
            if operator not in {"+", "-", "*", "/"}:
                print("Choose +, -, *, or /.")
                continue
            left = read_number("First number: ", ans_available, ans_value)
            right = read_number("Second number: ", ans_available, ans_value)
            try:
                result = calculate(left, operator, right)
                print(f"Result: {result:g}")
                ans_available = True
                ans_value = result
            except ValueError as error:
                print(error)
                # Do not update ans_available or ans_value on failed calculation
    except (EOFError, KeyboardInterrupt):
        print()
    print("Goodbye!")


if __name__ == "__main__":
    main()

